      "topic": "contract",
      "statement": "The before HTML tag scanner is defined to match a tag after the first '<'. In its double-quoted attribute state, a lone 0x80 byte fails the high-byte check and follows the zero-return path.",
      "evidence": [
        {"unit_id":"u-4ac7a77d6a4cd6bd9c55","start_line":4850,"end_line":4853,"role":"primary","dependency_reason":""},
