    {
      "topic": "contract",
      "statement": "The after HTML tag scanner's table sets the quoted-state bit for 0x80; its double-quoted state continues past that byte, and a closing quote followed by '>' reaches a positive matched-length return. Thus the scanner itself can match a tag shaped like <a x=\"\\x80\">.",
      "evidence": [
        {"unit_id":"u-bba2004f5e2ab75fff2e","start_line":4775,"end_line":4778,"role":"primary","dependency_reason":""},
        {"unit_id":"u-bba2004f5e2ab75fff2e","start_line":4792,"end_line":4801,"role":"primary","dependency_reason":""},
